public class Main {
    public static void main(String[] args) {
        String[] names = {"Asha", "Dev", "Mira"};
        int[] marks = {82, 91, 76};
        if (names.length != marks.length || marks.length == 0) throw new IllegalArgumentException("Invalid class data");
        int total = 0;
        for (int mark : marks) {
            if (mark < 0 || mark > 100) throw new IllegalArgumentException("Mark must be 0-100");
            total += mark;
        }
        for (int i = 0; i < names.length; i++) System.out.printf("%-8s %3d%n", names[i], marks[i]);
        System.out.printf("Average: %.2f%n", (double) total / marks.length);
    }
}
